"""Runs every example and writes RESULTS.md (description + source + real execution output)."""
import ast
import subprocess
import sys
from pathlib import Path

here = Path(__file__).parent
out = ["# Execution results - context engineering examples\n",
       "Generated by `python3 run_all.py`. Every block below is the real, captured output of the script shown with it.\n"]
failed = 0
for f in sorted(here.glob("ex[0-9][0-9]_*.py")):
    src = f.read_text()
    doc = ast.get_docstring(ast.parse(src)).strip().splitlines()
    res = subprocess.run([sys.executable, f.name], cwd=here, capture_output=True, text=True)
    failed += res.returncode != 0
    print(f"{'OK  ' if res.returncode == 0 else 'FAIL'} {f.name}")
    out += [f"\n## {doc[0]}\n", "\n".join(doc[1:]).strip() + "\n",
            f"\n<details><summary>Source: <code>{f.name}</code></summary>\n\n```python\n{src.strip()}\n```\n</details>\n",
            "\n**Execution result**\n", f"```text\n$ python3 {f.name}\n{(res.stdout + res.stderr).rstrip()}\n```\n"]
(here / "RESULTS.md").write_text("\n".join(out))
print("wrote RESULTS.md")
sys.exit(1 if failed else 0)
